import { resetTestDb, setupTestDb } from "../helpers/db";
const pw = "Abcdefghijk12";
const reg = (name: string, email: string) =>
  register({ name, email, password: pw, confirmPassword: pw, acceptTerms: true });
describe("signup", () => {
  beforeEach(async () => { await setupTestDb(); await resetTestDb(); resetRateLimits(); });
  it("names", async () => {
    const out: string[] = [];
    let i = 0;
    for (const n of ["Admin", "Billing", "Al", "J", "山田", "山田", "Admin", "x".repeat(80), "x".repeat(80), "a".repeat(42) + " bcdefgh", "a".repeat(42) + " bcdefgh"]) {
      const { org, user } = await reg(n, `U${i++}@Example.com`);
      out.push(`${org.slug} | ${org.name.length} | ${user.email} | ${org.plan}`);
      expect((await findSubscription(org.id))?.status).toBe("active");
    }
    console.log(out.join("\n"));
    const e = await reg("Z", "u0@example.COM").catch((x) => x);
    expect(toAppError(e).code).toBe("conflict");
    const l = await login({ email: "U1@EXAMPLE.com", password: pw, rememberMe: false });
    expect(l.user.email).toBe("u1@example.com");
    let last: unknown;
    for (let k = 0; k < 40; k++) last = await reg("Z", "u0@example.com").catch((x) => x);
    expect(toAppError(last).code).toBe("rate_limited");
  });
});
